from app.domain import MIN_EASE
from app.logic import clamp_ease


def test_clamp_ease_returns_ease_when_above_minimum():
    assert clamp_ease(2.5) == 2.5


def test_clamp_ease_returns_minimum_when_below_minimum():
    assert clamp_ease(1.0) == 1.3


def test_clamp_ease_returns_minimum_when_equal_to_minimum():
    assert clamp_ease(1.3) == 1.3


def test_clamp_ease_uses_domain_minimum_constant():
    assert clamp_ease(-4.0) == MIN_EASE


def test_clamp_ease_does_not_round_values_above_minimum():
    ease = 1.3000000000000003

    assert clamp_ease(ease) == ease

