import dataclasses
from datetime import date

from app.domain import Card, CardState, SchedulerSettings
from app.logic import is_leech


def make_card(lapses: int) -> Card:
    return Card(
        id="card-1",
        note_id="note-1",
        state=CardState.REVIEW,
        ease=2.5,
        interval_days=10,
        due_date=date(2026, 1, 1),
        lapses=lapses,
    )


def make_settings(threshold: int) -> SchedulerSettings:
    return SchedulerSettings(leech_threshold=threshold)


def test_is_leech_when_lapses_equal_threshold():
    assert is_leech(make_card(8), make_settings(8)) is True


def test_is_not_leech_when_lapses_are_below_threshold():
    assert is_leech(make_card(7), make_settings(8)) is False


def test_is_leech_when_lapses_exceed_positive_threshold():
    assert is_leech(make_card(9), make_settings(8)) is True


def test_zero_threshold_disables_leech_detection():
    assert is_leech(make_card(100), make_settings(0)) is False


def test_negative_threshold_disables_leech_detection():
    assert is_leech(make_card(100), make_settings(-1)) is False


def test_is_leech_does_not_modify_inputs():
    card = make_card(8)
    settings = make_settings(8)
    original_card = dataclasses.replace(card)
    original_settings = dataclasses.replace(settings)

    is_leech(card, settings)

    assert card == original_card
    assert settings == original_settings
